import React,{useState,useEffect,useRef,type FormEvent,type ReactNode} from 'react';
import {createRoot} from 'react-dom/client';
import {Compass,LayoutDashboard,ClipboardList,Route,CalendarDays,Settings,LogOut,ArrowUpRight,ArrowRight,Search,Bell,ChevronRight,ChevronLeft,Check,Plus,X,BookOpen,Target,Sparkles,BriefcaseBusiness,GraduationCap,ShieldCheck,Users,SlidersHorizontal,FileCheck,Send,Clock,Video,ExternalLink,CheckCircle2,Menu,LoaderCircle,LockKeyhole,ThumbsUp,ThumbsDown,Trash2,Eye,Code2,Palette,ChartNoAxesCombined,HeartHandshake,Building2,Lightbulb,Download} from 'lucide-react';
import {api} from './api';
import {questions,types,skillCatalog,skillName,interestInfo,rankCareers,type User,type Match,type Career,type Skills,type Role,type Weights} from '../../../packages/shared/domain';
import './styles.css';
const dateTime=(s:string)=>new Intl.DateTimeFormat('en-PK',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Karachi'}).format(new Date(s));
const roleLabel:Record<Role,string>={student:'Student',counsellor:'Counsellor',admin:'Administrator',expert:'Industry expert'};
const initials=(s:string)=>s.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const careerIcon=(c:Career)=>c.category==='Technology'?Code2:c.category==='Design and Media'?Palette:c.category==='People and Education'?HeartHandshake:c.category==='Business'?Building2:ChartNoAxesCombined;
function Button({children,className='',busy=false,...props}:React.ButtonHTMLAttributes<HTMLButtonElement>&{busy?:boolean}){return <button {...props} disabled={props.disabled||busy} className={`button ${className}`}>{busy?<LoaderCircle size={17} className="spin"/>:null}{children}</button>;}
function Empty({title,children,action}:{title:string;children:ReactNode;action?:ReactNode}){return <div className="empty"><Compass size={36}/><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Modal({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();const el=ref.current;return()=>el?.close();},[]);return <dialog className={`modal ${wide?'wide':''}`} ref={ref} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X/></button></div>{children}</dialog>;}
function Radar({scores}:{scores:Record<string,number>}){const cx=150,cy=135,r=88;const point=(i:number,n:number)=>{const a=-Math.PI/2+i*Math.PI/3;return [cx+Math.cos(a)*r*n,cy+Math.sin(a)*r*n];};return <figure className="radar"><svg viewBox="0 0 300 280" role="img" aria-label={`Interest profile: ${types.map(t=>`${interestInfo[t].name} ${scores[t]}`).join(', ')}`}><defs><linearGradient id="radarFill" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#b5f5c4" stopOpacity=".38"/><stop offset="1" stopColor="#a99aff" stopOpacity=".16"/></linearGradient></defs>{[.25,.5,.75,1].map(n=><polygon key={n} points={types.map((_,i)=>point(i,n).join(',')).join(' ')} fill="none" stroke="#363c43"/>)}{types.map((_,i)=><line key={i} x1={cx} y1={cy} x2={point(i,1)[0]} y2={point(i,1)[1]} stroke="#363c43"/>)}<polygon points={types.map((t,i)=>point(i,(scores[t]??0)/100).join(',')).join(' ')} fill="url(#radarFill)" stroke="#b5f5c4" strokeWidth="2"/>{types.map((t,i)=>{const [x,y]=point(i,1.3);const [px,py]=point(i,(scores[t]??0)/100);return <g key={t}><circle cx={px} cy={py} r="3" fill="#b5f5c4"/><text x={x} y={y} textAnchor="middle" fill="#adb4bf" fontSize="10">{interestInfo[t].name}</text><text x={x} y={y+15} textAnchor="middle" fill="#f5f7fb" fontSize="12" fontWeight="600">{scores[t]??0}</text></g>;})}</svg><figcaption>RIASEC interest scores · 0 to 100</figcaption></figure>;}
function CareerCard({career,match,onOpen,index}:{career:Career;match?:Match;onOpen:()=>void;index?:number}){const Icon=careerIcon(career);return <button className="career-card" onClick={onOpen}><div className="career-top"><span className={`career-icon color-${(index??0)%4}`}><Icon size={23}/></span>{match?<span className="match-pill">{match.score}% match</span>:<span className="subtle">Explore</span>}</div><span className="eyebrow">{career.category}</span><h3>{career.title}</h3><p>{career.summary}</p><div className="tags">{Object.keys(career.skills).slice(0,2).map(s=><span key={s}>{skillName(s)}</span>)}</div><div className="card-footer"><span>{match?`${match.gaps.length} skills to develop`:'View career profile'}</span><ArrowUpRight size={18}/></div></button>;}
function Login({mode,onLogin,notify}:{mode:string;onLogin:(u:User)=>void;notify:(s:string)=>void}){const [register,setRegister]=useState(false),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[busy,setBusy]=useState(false);async function submit(e?:FormEvent,demoRole?:string){e?.preventDefault();setBusy(true);try{const result=await api(`/auth/${register&&!demoRole?'register':'login'}`,'POST',demoRole?{email:`${demoRole}@careercompass.demo`,password:'CompassDemo!2026'}:register?{email,password,name}:{email,password});if(result.user)onLogin(result.user);else notify(result.message);}catch(e){notify((e as Error).message);}finally{setBusy(false);}}return <div className="auth-page"><div className="auth-story"><a href="#" className="brand"><span className="brand-symbol"><Compass/></span>CareerCompass<span className="brand-dot">.</span></a><div className="auth-story-content"><span className="eyebrow mint">A little clarity changes everything</span><h1>Your future.<br/>A direction<br/><span>that feels like you.</span></h1><p>Discover what drives you. Understand your options. Turn your next step into a plan.</p><div className="auth-orbit"><div className="orbit-ring"/><div className="orbit-ring second"/><Compass size={115} strokeWidth={.8}/><span className="orbit-tag one"><Sparkles size={15}/> Understand your strengths</span><span className="orbit-tag two"><Route size={15}/> Build your own path</span></div></div><div className="auth-bottom"><ShieldCheck size={17}/> Your profile. Your choices. Your control.</div></div><div className="auth-form-side"><div className="auth-form"><span className="tiny-label">YOUR NEXT CHAPTER STARTS HERE</span><h2>{register?'Find your direction':'Welcome back'}</h2><p>{register?'Create your free student account.':'Sign in and keep moving toward what matters to you.'}</p><form onSubmit={e=>submit(e)}>{register?<label>Full name<input required minLength={2} maxLength={80} value={name} onChange={e=>setName(e.target.value)} autoComplete="name"/></label>:null}<label>Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@university.edu.pk" autoComplete="email"/></label><label>Password<input type="password" required minLength={8} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters" autoComplete={register?'new-password':'current-password'}/></label><Button type="submit" busy={busy} className="primary full">{register?'Create student account':'Sign in'}<ArrowRight size={17}/></Button></form><p className="auth-toggle">{register?'Already have an account?':'New to CareerCompass?'} <button onClick={()=>setRegister(!register)}>{register?'Sign in':'Create an account'}</button></p>{mode==='demo'?<div className="demo-login"><span className="tiny-label">EXPLORE THE LOCAL DEMO</span><p>Sample accounts and educational data. Choose a workspace.</p><div>{(['student','counsellor','admin','expert'] as Role[]).map(r=><Button key={r} busy={busy} onClick={()=>submit(undefined,r)}>{roleLabel[r]}<ArrowUpRight size={14}/></Button>)}</div></div>:<p className="fine-print">Staff accounts are assigned by an administrator. If email confirmation is enabled, confirm your email before signing in.</p>}</div><span className="auth-footnote">Made for curious minds and meaningful next steps.</span></div></div>;}
function App(){
 const [meta,setMeta]=useState<any>(),[user,setUser]=useState<User|null>(null),[data,setData]=useState<any>(),[careers,setCareers]=useState<Career[]>([]),[loading,setLoading]=useState(true),[fatal,setFatal]=useState(''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[page,setPage]=useState(location.hash.slice(1)||'overview'),[query,setQuery]=useState(''),[detail,setDetail]=useState<Career|null>(null),[roadmapId,setRoadmapId]=useState(''),[notifications,setNotifications]=useState(false),[mobile,setMobile]=useState(false);
 const notify=(s:string)=>setToast(s);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),6500);return()=>clearTimeout(t);}},[toast]);
 useEffect(()=>{const fn=()=>setPage(location.hash.slice(1)||'overview');window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn);},[]);
 const go=(p:string)=>{setPage(p);location.hash=p;setMobile(false);window.scrollTo({top:0,behavior:'smooth'});};
 async function load(){const [d,c]=await Promise.all([api('/dashboard'),api<Career[]>('/careers')]);setData(d);setCareers(c);}
 useEffect(()=>{(async()=>{try{setMeta(await api('/meta'));try{setUser(await api<User>('/me'));}catch{setUser(null);}}catch(e){setFatal((e as Error).message);}finally{setLoading(false);}})();},[]);
 useEffect(()=>{if(!user){setData(undefined);return;}load().catch(e=>notify(e.message));const t=setInterval(()=>api('/dashboard').then(setData).catch(()=>{}),30000);return()=>clearInterval(t);},[user?.id]);
 async function act(fn:()=>Promise<unknown>,message?:string){setBusy(true);try{await fn();await load();if(message)notify(message);}catch(e){notify((e as Error).message);}finally{setBusy(false);}}
 async function logout(){try{await api('/auth/logout','POST');setUser(null);go('overview');}catch(e){notify((e as Error).message);}}
 const matches:Match[]=data?.matches??[];const assessment=data?.assessment;const allMatches=assessment?rankCareers(assessment.scores,assessment.skills,user?.degree??null,careers,data.weights):[];
 const navs:Record<Role,{id:string;label:string;icon:any}[]>={
  student:[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'assessment',label:'My assessment',icon:ClipboardList},{id:'matches',label:'Career matches',icon:BriefcaseBusiness},{id:'roadmap',label:'Learning roadmap',icon:Route},{id:'consultations',label:'Consultations',icon:CalendarDays}],
  counsellor:[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'availability',label:'My availability',icon:CalendarDays},{id:'sessions',label:'Student sessions',icon:Users}],
  admin:[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'knowledge',label:'Career knowledge base',icon:BookOpen},{id:'reviews',label:'Review queue',icon:FileCheck},{id:'users',label:'User management',icon:Users},{id:'scoring',label:'Scoring settings',icon:SlidersHorizontal}],
  expert:[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'submit',label:'Submit an update',icon:Send},{id:'contributions',label:'My contributions',icon:FileCheck}]
 };
 const safePage=user&&([...navs[user.role].map(n=>n.id),'settings'].includes(page))?page:'overview';
 const showRoadmap=(id:string)=>{setRoadmapId(id);setDetail(null);go('roadmap');};
 const toastUI=toast?<div className="toast" role="status"><span>{toast}</span><button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={17}/></button></div>:null;
 if(loading)return <div className="loading-screen"><Compass size={40}/><span>Finding your direction…</span></div>;
 if(fatal)return <div className="loading-screen"><h2>Could not reach CareerCompass</h2><p>{fatal}</p><Button onClick={()=>location.reload()}>Try again</Button></div>;
 if(!user)return <><Login mode={meta?.mode} onLogin={u=>{setUser(u);go('overview');}} notify={notify}/>{toastUI}</>;
 const activeNav=navs[user.role].find(n=>n.id===safePage);
 return <div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><a className="brand" href="#overview"><span className="brand-symbol"><Compass size={23}/></span>CareerCompass<span className="brand-dot">.</span></a><div className="workspace-label">{roleLabel[user.role]} workspace</div><nav aria-label="Main navigation">{navs[user.role].map(n=><button key={n.id} className={safePage===n.id?'active':''} onClick={()=>go(n.id)}><n.icon size={19}/>{n.label}{n.id==='matches'&&matches.length?<span className="nav-count">{matches.length}</span>:null}{n.id==='reviews'&&data?.proposals?.filter((p:any)=>p.status==='pending').length?<span className="nav-count">{data.proposals.filter((p:any)=>p.status==='pending').length}</span>:null}</button>)}</nav>{user.role==='student'?<div className="sidebar-note"><div className="small-icon"><Lightbulb size={19}/></div><h4>Clarity comes from<br/>taking the next step.</h4><p>Your path can change.<br/>Keep exploring.</p><button onClick={()=>go('consultations')}>Talk to a counsellor<ArrowUpRight size={15}/></button></div>:null}<div className="sidebar-bottom"><button className={safePage==='settings'?'selected':''} onClick={()=>go('settings')}><Settings size={19}/>Settings</button><button onClick={logout}><LogOut size={19}/>Sign out</button><div className="sidebar-profile"><span className="avatar">{initials(user.name)}</span><div><strong>{user.name}</strong><span>{roleLabel[user.role]}</span></div><span className="online-dot"/></div></div></aside>{mobile?<button className="sidebar-backdrop" aria-label="Close navigation" onClick={()=>setMobile(false)}/>:null}<main className="main"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Open navigation"><Menu size={21}/></button><span>My workspace</span><ChevronRight size={14}/><strong>{activeNav?.label??'Settings'}</strong></div><div className="topbar-actions">{user.role==='student'?<label className="search-box"><Search size={17}/><input aria-label="Search careers" placeholder="Search careers…" value={query} onChange={e=>{setQuery(e.target.value);if(safePage!=='matches')go('matches');}}/><kbd>/</kbd></label>:null}<span className="demo-badge">{meta.mode==='demo'?'LOCAL DEMO':'CONNECTED'}</span><button className="icon-button notification-trigger" aria-label="Notifications" onClick={()=>setNotifications(!notifications)}><Bell size={20}/>{data?.notifications?.some((n:any)=>!n.read)?<i/>:null}</button><span className="avatar small">{initials(user.name)}</span></div>{notifications?<section className="notification-popover"><div className="section-head"><h3>Notifications</h3><button className="text-button" onClick={()=>act(()=>api('/notifications/read','PUT'))}>Mark all read</button></div>{data?.notifications?.length?data.notifications.map((n:any)=><div key={n.id} className={`notice ${n.read?'':'unread'}`}><p>{n.message}</p><small>{dateTime(n.created_at)}</small></div>):<p className="muted">You’re all caught up.</p>}</section>:null}</header><div className="content">{!data?<div className="panel loading-panel"><LoaderCircle className="spin"/><p>Loading your workspace…</p><Button onClick={()=>load().catch(e=>notify(e.message))}>Retry</Button></div>:<>
 {safePage==='overview'&&user.role==='student'?<StudentOverview user={user} data={data} go={go} open={setDetail}/>:null}
 {safePage==='assessment'?<AssessmentPage draft={data.draft} busy={busy} onSave={p=>api('/assessment-draft','PUT',p)} onSubmit={p=>act(async()=>{await api('/assessments','POST',p);go('matches');},'Assessment complete. Your career matches are ready.')} notify={notify}/>:null}
 {safePage==='matches'?<MatchesPage careers={careers} matches={matches} query={query} setQuery={setQuery} open={setDetail} hasAssessment={!!assessment} go={go}/>:null}
 {safePage==='roadmap'?<RoadmapPage id={roadmapId||matches[0]?.career.id} matches={allMatches} setId={setRoadmapId} data={data} busy={busy} act={act} go={go}/>:null}
 {safePage==='consultations'?<Consultations data={data} busy={busy} act={act}/>:null}
 {user.role==='counsellor'&&['overview','availability','sessions'].includes(safePage)?<CounsellorPage page={safePage} data={data} user={user} busy={busy} act={act} notify={notify}/>:null}
 {user.role==='admin'&&safePage==='overview'?<AdminOverview data={data} careers={careers} go={go}/>:null}
 {user.role==='admin'&&safePage==='knowledge'?<KnowledgePage careers={careers} busy={busy} act={act}/>:null}
 {user.role==='admin'&&safePage==='reviews'?<Proposals data={data.proposals} admin busy={busy} act={act}/>:null}
 {user.role==='admin'&&safePage==='users'?<UsersPage users={data.users} self={user.id} busy={busy} act={act}/>:null}
 {user.role==='admin'&&safePage==='scoring'?<ScoringPage weights={data.weights} busy={busy} act={act}/>:null}
 {user.role==='expert'?<ExpertPage page={safePage} careers={careers} proposals={data.proposals} busy={busy} act={act} go={go}/>:null}
 {safePage==='settings'?<SettingsPage user={user} onUser={setUser} busy={busy} act={act} onDelete={()=>{setUser(null);go('overview');}} notify={notify}/>:null}
 </>}<footer className="page-footer"><span><Compass size={13}/> CareerCompass</span><span>Explore thoughtfully. Decide for yourself.</span><span>{meta.mode==='demo'?'Educational demo · sample data':'Career exploration platform'}</span></footer></div></main>{detail?<CareerDetail career={detail} match={allMatches.find(m=>m.career.id===detail.id)} onClose={()=>setDetail(null)} roadmap={showRoadmap} feedback={data?.feedback?.find((f:any)=>f.career_id===detail.id)} busy={busy} act={act}/>:null}{toastUI}</div>;
}
function PageHeading({eyebrow,title,children,action}:{eyebrow?:string;title:string;children?:ReactNode;action?:ReactNode}){return <div className="page-heading"><div>{eyebrow?<span className="eyebrow">{eyebrow}</span>:null}<h1>{title}</h1>{children?<p>{children}</p>:null}</div>{action}</div>;}
function Stat({label,value,description,icon:Icon,color='mint'}:{label:string;value:ReactNode;description:string;icon:any;color?:string}){return <div className="stat-card"><div><span>{label}</span><strong>{value}</strong><small>{description}</small></div><span className={`stat-icon ${color}`}><Icon size={21}/></span></div>;}
function StudentOverview({user,data,go,open}:{user:User;data:any;go:(p:string)=>void;open:(c:Career)=>void}){const matches:Match[]=data.matches;const a=data.assessment;const top=a?[...types].sort((x,y)=>a.scores[y]-a.scores[x]):[];const upcoming=data.bookings.filter((b:any)=>b.status==='booked'&&new Date(b.starts_at)>new Date()).sort((a:any,b:any)=>new Date(a.starts_at).getTime()-new Date(b.starts_at).getTime())[0];const complete=data.milestones.filter((m:any)=>m.complete).length;return <><PageHeading title={`A little more clarity, ${user.name.split(' ')[0]}.`} eyebrow={new Intl.DateTimeFormat('en-PK',{weekday:'long',month:'long',day:'numeric',timeZone:'Asia/Karachi'}).format(new Date())}>Your interests are the starting point. Let’s see where they can take you.</PageHeading><section className="hero-panel"><div className="hero-copy"><span className="hero-kicker"><span className="live-dot"/> YOUR FUTURE IS TAKING SHAPE</span><h2>{a?<>There’s a direction<br/>with <em>your name on it.</em></>:<>Great futures start<br/>with <em>knowing yourself.</em></>}</h2><p>{a?'You’ve taken the first step. Explore your matches and build the skills that bring your next chapter closer.':'Discover your interests through 48 short activities, then turn your strengths into a practical career plan.'}</p><Button className="primary" onClick={()=>go(a?'matches':'assessment')}>{a?'Explore my matches':'Discover my interests'}<ArrowUpRight size={18}/></Button><span className="hero-caption">{a?'Your path is yours to choose.':'About 12–15 minutes · save and return anytime'}</span></div><div className="hero-art" aria-hidden="true"><div className="hero-grid"/><div className="compass-orbit outer"/><div className="compass-orbit inner"/><div className="compass-center"><Compass strokeWidth={.7}/></div><span className="north">N</span><span className="art-star">✦</span><div className="floating-label"><span className="mini-dot"/> A path that fits you<ArrowUpRight size={14}/></div><div className="art-coordinate">EXPLORE · DISCOVER · GROW</div></div></section><div className="stats-grid"><Stat label="Career matches" value={matches.length.toString().padStart(2,'0')} description={a?'Personalised to your profile':'Complete your assessment'} icon={BriefcaseBusiness}/><Stat label="Your leading interest" value={top[0]?interestInfo[top[0]].name:'Not explored yet'} description={top[1]?`Followed by ${interestInfo[top[1]].name.toLowerCase()}`:'Start discovering what drives you'} icon={Sparkles} color="violet"/><Stat label="Learning milestones" value={complete.toString().padStart(2,'0')} description="Completed on your roadmaps" icon={Route} color="peach"/></div><div className="dashboard-columns"><section className="panel interest-panel"><div className="section-head"><div><h2>Your interest fingerprint</h2><p>Six dimensions. One unique perspective.</p></div><span className="pill">RIASEC</span></div>{a?<Radar scores={a.scores}/>:<Empty title="Start with your interests">Your profile will appear here after your assessment.</Empty>}<div className="interest-legend">{top.slice(0,3).map(t=><span key={t}><i style={{background:interestInfo[t].color}}/>{interestInfo[t].name}</span>)}</div><button className="panel-link" onClick={()=>go('assessment')}>{a?'Revisit your assessment':'Take your first assessment'}<ArrowRight size={16}/></button></section><section className="panel next-panel"><div className="section-head"><div><h2>Your next moves</h2><p>Small steps. Real progress.</p></div><Target size={20}/></div><button className="next-move" onClick={()=>go(a?'matches':'assessment')}><span className="step-icon mint">01</span><div><h3>{a?'Find a career that clicks':'Get to know your interests'}</h3><p>{a?'See the reasons behind your top matches.':'48 activities to discover your RIASEC profile.'}</p></div><ArrowUpRight size={18}/></button><button className="next-move" onClick={()=>go('roadmap')}><span className="step-icon violet">02</span><div><h3>Turn a skill gap into a goal</h3><p>Choose a path and follow a learning roadmap.</p></div><ArrowUpRight size={18}/></button><button className="next-move" onClick={()=>go('consultations')}><span className="step-icon peach">03</span><div><h3>Get a human perspective</h3><p>Talk it through with a career counsellor.</p></div><ArrowUpRight size={18}/></button><div className="upcoming-inline"><span className="mini-calendar"><CalendarDays size={22}/></span><div><strong>{upcoming?'Your next consultation':'A conversation can help'}</strong><p>{upcoming?`${dateTime(upcoming.starts_at)} PKT`:'Find a time to discuss your next step.'}</p></div><button className="text-button" onClick={()=>go('consultations')}>{upcoming?'View':'Book'}<ChevronRight size={15}/></button></div></section></div><div className="section-head outside"><div><h2>Possibilities worth exploring</h2><p>Your strongest matches, with the reasoning made visible.</p></div><button className="text-button" onClick={()=>go('matches')}>View all matches<ArrowRight size={16}/></button></div>{matches.length?<div className="career-grid">{matches.slice(0,3).map((m,i)=><CareerCard key={m.career.id} career={m.career} match={m} index={i} onOpen={()=>open(m.career)}/>)}</div>:<div className="panel"><Empty title="Your possibilities start here" action={<Button className="primary" onClick={()=>go('assessment')}>Take the assessment<ArrowRight size={16}/></Button>}>Complete your interest and skill profile to see your matches.</Empty></div>}<p className="education-note"><ShieldCheck size={15}/> Match scores support exploration. Starter career profiles and this original questionnaire require review and pilot validation.</p></>;}
function AssessmentPage({draft,busy,onSave,onSubmit,notify}:{draft:any;busy:boolean;onSave:(p:any)=>Promise<any>;onSubmit:(p:any)=>void;notify:(s:string)=>void}){const [answers,setAnswers]=useState<number[]>(draft?.answers??Array(48).fill(0)),[skills,setSkills]=useState<Skills>(draft?.skills??{}),[step,setStep]=useState(draft?.step??0),[saving,setSaving]=useState(false);const count=answers.filter(Boolean).length;const batch=questions.slice(step*8,step*8+8);async function save(){setSaving(true);try{await onSave({answers,skills,step});notify('Progress saved to your account.');}catch(e){notify((e as Error).message);}finally{setSaving(false);}}const canContinue=step<6?answers.slice(step*8,step*8+8).every(Boolean):skillCatalog.every(s=>skills[s.id]);return <><PageHeading title="Discover what drives you" eyebrow="MY ASSESSMENT" action={<Button onClick={save} busy={saving}><Download size={16}/>Save progress</Button>}>Rate what you enjoy, then tell us which skills you have practised.</PageHeading><div className="assessment-layout"><aside className="panel assessment-aside"><h3>A clearer picture of you</h3><p>This educational questionnaire explores interests, not ability or a fixed personality.</p><div className="assessment-progress"><span>{count} of 48 activities</span><strong>{Math.round(count/48*100)}%</strong></div><div className="progress-track"><i style={{width:`${count/48*100}%`}}/></div>{Array.from({length:7},(_,i)=><button key={i} className={`assessment-step ${step===i?'active':''}`} onClick={()=>setStep(i)}><span>{i<step?<Check size={14}/>:i+1}</span><div><strong>{i===6?'Your skills':`Interests · Part ${i+1}`}</strong><small>{i===6?'16 self-ratings':'8 short activities'}</small></div></button>)}<p className="fine-print">Choose based on what interests you, even if you have never tried it. This is an original 48-item RIASEC-based student project questionnaire, not a standardised O*NET test.</p></aside><section className="panel questionnaire"><div className="section-head"><div><span className="eyebrow">STEP {step+1} OF 7</span><h2>{step===6?'What have you practised?':'Would you enjoy doing this?'}</h2><p>{step===6?'1 = beginner · 5 = advanced. Be honest about your current level.':'1 = strongly dislike · 5 = strongly enjoy. There are no right answers.'}</p></div><span className="pill"><Clock size={13}/>12–15 min</span></div>{step<6?<><div className="scale-legend"><span>Strongly dislike</span><span>Strongly enjoy</span></div>{batch.map((q,n)=>{const idx=step*8+n;return <fieldset className="question" key={q.id}><legend><span>{String(idx+1).padStart(2,'0')}</span>{q.text}</legend><div className="rating-options">{[1,2,3,4,5].map(v=><label key={v} className={answers[idx]===v?'chosen':''}><input type="radio" name={q.id} value={v} checked={answers[idx]===v} onChange={()=>setAnswers(a=>a.map((x,i)=>i===idx?v:x))}/><span>{v}</span><small>{['Dislike a lot','Dislike','Neutral','Enjoy','Enjoy a lot'][v-1]}</small></label>)}</div></fieldset>;})}</>:<div className="skills-form">{skillCatalog.map(s=><label key={s.id}>{s.name}<select value={skills[s.id]??''} onChange={e=>setSkills({...skills,[s.id]:Number(e.target.value)})}><option value="" disabled>Select level</option>{[1,2,3,4,5].map(v=><option key={v} value={v}>{v} · {['Beginner','Basic','Working knowledge','Proficient','Advanced'][v-1]}</option>)}</select></label>)}</div>}<div className="questionnaire-actions"><Button disabled={step===0||busy} onClick={()=>{setStep(step-1);window.scrollTo(0,0);}}><ChevronLeft size={16}/>Back</Button><span>{step===6?`${Object.keys(skills).length}/16 skills rated`:`${answers.slice(step*8,step*8+8).filter(Boolean).length}/8 answered`}</span><Button className="primary" disabled={!canContinue||busy||(step===6&&count!==48)} busy={busy} onClick={()=>{if(step<6){setStep(step+1);window.scrollTo(0,0);}else onSubmit({answers,skills});}}>{step===6?'See my matches':'Continue'}<ArrowRight size={17}/></Button></div></section></div></>;}
function MatchesPage({careers,matches,query,setQuery,open,hasAssessment,go}:{careers:Career[];matches:Match[];query:string;setQuery:(s:string)=>void;open:(c:Career)=>void;hasAssessment:boolean;go:(s:string)=>void}){const [tab,setTab]=useState<'matches'|'all'>(hasAssessment?'matches':'all'),[category,setCategory]=useState('All fields');const source=tab==='matches'?matches.map(m=>m.career):careers;const filtered=source.filter(c=>(category==='All fields'||c.category===category)&&`${c.title} ${c.summary} ${Object.keys(c.skills).map(skillName).join(' ')}`.toLowerCase().includes(query.toLowerCase()));return <><PageHeading title="A world of possible directions" eyebrow="CAREER EXPLORATION">Look beyond a job title. Understand what fits and what you could learn next.</PageHeading><div className="filter-bar"><div className="tabs"><button className={tab==='matches'?'active':''} onClick={()=>setTab('matches')}>Your top 10<span>{matches.length}</span></button><button className={tab==='all'?'active':''} onClick={()=>setTab('all')}>Explore all careers<span>{careers.length}</span></button></div><div className="filter-controls"><label className="search-box"><Search size={17}/><input aria-label="Filter career list" placeholder="Search a title or skill" value={query} onChange={e=>setQuery(e.target.value)}/></label><select aria-label="Career field" value={category} onChange={e=>setCategory(e.target.value)}>{['All fields',...new Set(careers.map(c=>c.category))].map(c=><option key={c}>{c}</option>)}</select></div></div>{tab==='matches'&&!hasAssessment?<div className="panel"><Empty title="Get your personal matches" action={<Button className="primary" onClick={()=>go('assessment')}>Take assessment<ArrowRight size={16}/></Button>}>Your interest and skill ratings help us explain each recommendation.</Empty></div>:filtered.length?<><div className="results-label"><span>{filtered.length} {tab==='matches'?'personalised matches':'careers to explore'}</span><span>{tab==='matches'?'Ranked by current hybrid score':'Browse the starter knowledge base'}</span></div><div className="career-grid">{filtered.map((c,i)=><CareerCard key={c.id} career={c} match={matches.find(m=>m.career.id===c.id)} index={i} onOpen={()=>open(c)}/>)}</div></>:<Empty title="No careers found">Try a different title, skill or field.</Empty>}<p className="education-note"><ShieldCheck size={15}/> Scores are weighted similarity estimates, not probabilities of career success. Degree mappings and skill levels are starter editorial data.</p></>;}
function CareerDetail({career,match,onClose,roadmap,feedback,busy,act}:{career:Career;match?:Match;onClose:()=>void;roadmap:(id:string)=>void;feedback:any;busy:boolean;act:(fn:()=>Promise<unknown>,s?:string)=>void}){const [rating,setRating]=useState(feedback?.rating??0);return <Modal title={career.title} onClose={onClose} wide><div className="detail-intro"><span className="eyebrow">{career.category}</span><p>{career.summary}</p>{match?<div className="detail-score"><strong>{match.score}<small>%</small></strong><div><h3>Current profile match</h3><p>Interest alignment, skill readiness and academic fit.</p></div></div>:null}</div>{match?<><h3>Why this career appears</h3><p className="muted">The three weighted contributions add up to your match score.</p><div className="factor-list">{match.factors.map((f,i)=><div className="factor" key={f.label}><div className="factor-head"><span><i style={{background:['#b5f5c4','#b0a0ff','#f2b08d'][i]}}/>{f.label}</span><strong>+{f.contribution.toFixed(1)} points</strong></div><div className="progress-track"><i style={{width:`${f.value}%`,background:['#b5f5c4','#b0a0ff','#f2b08d'][i]}}/></div><p>{f.detail} Component score: {f.value}%.</p></div>)}</div><div className="detail-columns"><section><h3>Skills to develop</h3>{match.gaps.length?match.gaps.map(g=><div className="compact-row" key={g.skill}><span>{skillName(g.skill)}</span><span>Level {g.current} → {g.required}</span></div>):<p>You meet all current starter skill levels.</p>}</section><section><h3>Suggested degree backgrounds</h3><p className="muted">{career.degrees.join(', ')||'Open to multiple degree backgrounds.'}</p><p className="fine-print">These suggestions are not formal admission or professional licensing requirements.</p></section></div><Button className="primary full" onClick={()=>roadmap(career.id)}>Build my learning roadmap<Route size={18}/></Button>{feedback!==undefined||true?<section className="feedback-section"><h3>Does this direction feel relevant?</h3><p>Your feedback helps evaluate the recommendations.</p><div className="feedback-actions"><Button disabled={busy} className={feedback?.relevant===true?'selected':''} onClick={()=>act(()=>api(`/careers/${career.id}/feedback`,'PUT',{relevant:true,rating:rating||null}),'Feedback saved.')}><ThumbsUp size={16}/>Relevant</Button><Button disabled={busy} className={feedback?.relevant===false?'selected':''} onClick={()=>act(()=>api(`/careers/${career.id}/feedback`,'PUT',{relevant:false,rating:rating||null}),'Feedback saved.')}><ThumbsDown size={16}/>Not relevant</Button><label>Relevance rating<select value={rating} onChange={e=>setRating(Number(e.target.value))}><option value={0}>Optional</option>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} / 5</option>)}</select></label></div><p className="fine-print">Choose a rating first, then save it with Relevant or Not relevant. Only careers in your top 10 can receive feedback.</p></section>:null}</>:<p className="muted">Complete an assessment to see your match explanation and skill roadmap.</p>}<div className="source-note"><span>{career.reviewStatus}</span><a href={career.source} target="_blank" rel="noreferrer">Background source<ExternalLink size={13}/></a></div></Modal>;}
function RoadmapPage({id,matches,setId,data,busy,act,go}:{id:string;matches:Match[];setId:(s:string)=>void;data:any;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void;go:(s:string)=>void}){const match=matches.find(m=>m.career.id===id);if(!match)return <><PageHeading title="Make your next step practical" eyebrow="LEARNING ROADMAP"/><div className="panel"><Empty title="Choose a direction first" action={<Button className="primary" onClick={()=>go('matches')}>Explore career matches<ArrowRight size={16}/></Button>}>Complete your assessment and choose a career to reveal its skill gaps.</Empty></div></>;const done=match.gaps.filter(g=>data.milestones.some((m:any)=>m.career_id===id&&m.skill===g.skill&&m.complete)).length;return <><PageHeading title="A direction becomes a plan" eyebrow="LEARNING ROADMAP">Close one skill gap at a time. Progress is self-reported and does not change your assessed skill ratings.</PageHeading><div className="roadmap-layout"><aside className="panel roadmap-summary"><span className="eyebrow">YOUR CHOSEN DIRECTION</span><label className="sr-only" htmlFor="roadmap-career">Career</label><select id="roadmap-career" value={id} onChange={e=>setId(e.target.value)}>{matches.map(m=><option key={m.career.id} value={m.career.id}>{m.career.title}</option>)}</select><span className="big-match">{match.score}<small>%</small></span><span className="muted">current profile match</span><div className="roadmap-progress"><div><strong>{done} of {match.gaps.length}</strong><span> milestones complete</span></div><div className="progress-track"><i style={{width:`${match.gaps.length?done/match.gaps.length*100:100}%`}}/></div></div><h3>Your learning approach</h3><p>Start with your largest gaps. Explore the linked resource, practise on a small project, then mark the milestone complete.</p><p className="fine-print">Resource starting points are curated. Course availability and cost can change. Reassess when your actual skill levels improve.</p></aside><section><div className="section-head outside"><div><h2>Your learning milestones</h2><p>Ordered by the distance to the career’s required skill level.</p></div><span className="pill"><Route size={14}/>{match.gaps.length} milestones</span></div>{match.gaps.length?match.gaps.map((g,i)=>{const complete=data.milestones.some((m:any)=>m.career_id===id&&m.skill===g.skill&&m.complete);return <article className={`milestone panel ${complete?'complete':''}`} key={g.skill}><div className="milestone-number">{complete?<Check size={20}/>:String(i+1).padStart(2,'0')}</div><div className="milestone-body"><div className="section-head"><h3>{skillName(g.skill)}</h3><span className="pill">Level {g.current} → {g.required}</span></div><p>Build from your current level {g.current} toward level {g.required}. Use the resource, then create a small example that demonstrates what you learned.</p><a className="resource-link" href={g.url} target="_blank" rel="noreferrer"><BookOpen size={17}/>{g.resource}<ExternalLink size={14}/></a><label className="checkbox-label"><input type="checkbox" checked={complete} disabled={busy} onChange={()=>act(()=>api(`/careers/${id}/milestones/${g.skill}`,'PUT',{complete:!complete}))}/>{complete?'Milestone complete':'Mark complete after practising'}</label></div></article>;}):<div className="panel"><Empty title="You meet the current skill levels">Explore a practical project or discuss your next steps with a counsellor.</Empty></div>}</section></div></>;}
function Consultations({data,busy,act}:{data:any;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void}){const [people,setPeople]=useState<any[]>([]),[slots,setSlots]=useState<any[]>([]),[error,setError]=useState(''),[person,setPerson]=useState<any>(),[slot,setSlot]=useState<any>(),[consent,setConsent]=useState(false),[step,setStep]=useState(0),[booking,setBooking]=useState(false);useEffect(()=>{Promise.all([api('/counsellors'),api('/slots')]).then(([p,s])=>{setPeople(p);setSlots(s);}).catch(e=>setError(e.message));},[data]);const upcoming=data.bookings.filter((b:any)=>b.status==='booked'&&new Date(b.starts_at)>new Date());return <><PageHeading title="Sometimes a conversation is the next step" eyebrow="CONSULTATIONS" action={<Button className="primary" onClick={()=>{setBooking(true);setStep(0);setPerson(undefined);setSlot(undefined);setConsent(false);}}><Plus size={17}/>Book a session</Button>}>30 minutes with a counsellor. You choose whether to share your assessment.</PageHeading><div className="stats-grid"><Stat label="Upcoming sessions" value={upcoming.length} description="All times shown in Pakistan time" icon={CalendarDays}/><Stat label="Available counsellors" value={people.length} description="Explore a different perspective" icon={Users} color="violet"/><Stat label="Your privacy" value="Your choice" description="Consent is specific to each booking" icon={ShieldCheck} color="peach"/></div><section className="panel"><div className="section-head"><div><h2>Your consultations</h2><p>Manage bookings and control who can see your results.</p></div><span className="pill">Asia/Karachi · PKT</span></div>{data.bookings.length?<div className="booking-list">{data.bookings.map((b:any)=><article className={`booking-card ${b.status==='cancelled'?'cancelled':''}`} key={b.id}><span className="avatar large">{initials(b.counsellor_name)}</span><div className="booking-info"><h3>{b.counsellor_name}</h3><p><CalendarDays size={14}/>{dateTime(b.starts_at)} PKT<Clock size={14}/>30 min</p><span className={`status ${b.status}`}>{b.status}</span></div><div className="booking-actions">{b.status==='booked'?<><label className="checkbox-label"><input type="checkbox" disabled={busy} checked={b.consent} onChange={()=>act(()=>api(`/bookings/${b.id}`,'PATCH',{consent:!b.consent}),'Sharing preference updated.')}/>{b.consent?'Assessment shared':'Assessment private'}</label><Button disabled={busy} className="danger ghost" onClick={()=>act(()=>api(`/bookings/${b.id}`,'PATCH',{status:'cancelled'}),'Session cancelled.')}>Cancel session</Button></>:null}</div></article>)}</div>:<Empty title="No sessions booked yet" action={<Button onClick={()=>setBooking(true)}>Find a counsellor<ArrowRight size={16}/></Button>}>Bring your questions, your interests and an open mind.</Empty>}<p className="fine-print">CareerCompass records the booking. Meeting arrangements happen outside the platform; video calls and payments are outside this semester’s scope.</p></section>{error?<p role="alert" className="error-text">{error}</p>:null}{booking?<Modal title="Book a consultation" onClose={()=>setBooking(false)}><div className="booking-steps">{['Counsellor','Time','Sharing','Confirm'].map((s,i)=><span className={step===i?'active':step>i?'done':''} key={s}><i>{step>i?<Check size={13}/>:i+1}</i>{s}</span>)}</div>{step===0?<><h3>Who would you like to talk to?</h3><div className="counsellor-choices">{people.length?people.map(p=><button className={`counsellor-choice ${person?.id===p.id?'selected':''}`} key={p.id} onClick={()=>{setPerson(p);setSlot(undefined);}}><span className="avatar large">{initials(p.name)}</span><div><h3>{p.name}</h3><span className="mint-text">{p.specialty||'Career exploration'}</span><p>{p.bio||'Explore your goals and discuss your next steps.'}</p><small>{slots.filter(s=>s.counsellor_id===p.id).length} open slots</small></div>{person?.id===p.id?<CheckCircle2 size={21}/>:null}</button>):<Empty title="No counsellors available">An administrator can assign counsellor accounts. Counsellors can then publish slots.</Empty>}</div></>:null}{step===1?<><h3>Choose an available time</h3><p className="muted">All sessions last 30 minutes. Times are shown in PKT.</p><div className="slot-grid">{slots.filter(s=>s.counsellor_id===person?.id).map(s=><button key={s.id} className={slot?.id===s.id?'selected':''} onClick={()=>setSlot(s)}><CalendarDays size={17}/>{dateTime(s.starts_at)}</button>)}</div>{!slots.some(s=>s.counsellor_id===person?.id)?<p>No slots available. Try another counsellor.</p>:null}</>:null}{step===2?<div className="sharing-choice"><ShieldCheck size={38}/><h3>Your results stay under your control</h3><p>Sharing lets this counsellor view your interest scores, skills, optional degree and semester, and career matches for this booking. Raw questionnaire answers and CGPA are not shared.</p><label className="checkbox-label large-check"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>Share my assessment for this booking</label><p className="fine-print">This is optional. You can book without sharing and withdraw consent from your consultations page.</p></div>:null}{step===3?<div className="booking-review"><CheckCircle2 size={35}/><h3>Your next conversation</h3><div className="compact-row"><span>Counsellor</span><strong>{person?.name}</strong></div><div className="compact-row"><span>When</span><strong>{slot?dateTime(slot.starts_at):''} PKT</strong></div><div className="compact-row"><span>Duration</span><strong>30 minutes</strong></div><div className="compact-row"><span>Assessment sharing</span><strong>{consent?'Shared for this booking':'Private'}</strong></div></div>:null}<div className="modal-actions"><Button disabled={step===0||busy} onClick={()=>setStep(step-1)}><ChevronLeft size={16}/>Back</Button><Button busy={busy} className="primary" disabled={(step===0&&!person)||(step===1&&!slot)} onClick={()=>{if(step<3)setStep(step+1);else act(async()=>{await api('/bookings','POST',{slotId:slot.id,consent});setBooking(false);},'Your consultation is booked. Both parties have been notified.');}}>{step===3?'Confirm booking':'Continue'}<ArrowRight size={16}/></Button></div></Modal>:null}</>;}
function CounsellorPage({page,data,user,busy,act,notify}:{page:string;data:any;user:User;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void;notify:(s:string)=>void}){const [starts,setStarts]=useState(''),[selected,setSelected]=useState<string>(),[context,setContext]=useState<any>(),[note,setNote]=useState(''),[fetching,setFetching]=useState(false);const selectedBooking=data.bookings.find((b:any)=>b.id===selected);const upcoming=data.bookings.filter((b:any)=>b.status==='booked'&&new Date(b.starts_at)>new Date());async function open(b:any){setSelected(b.id);setContext(undefined);setNote('');setFetching(true);try{const n=await api(`/bookings/${b.id}/note`);setNote(n.note);if(b.consent&&b.status==='booked')setContext(await api(`/bookings/${b.id}/context`));}catch(e){notify((e as Error).message);}finally{setFetching(false);}}return <><PageHeading title={page==='availability'?'Make room for a conversation':page==='sessions'?'Support the next step':`Welcome back, ${user.name.split(' ')[0]}.`} eyebrow="COUNSELLOR WORKSPACE">Manage your availability and support students with the context they choose to share.</PageHeading>{page==='overview'?<div className="stats-grid"><Stat label="Upcoming sessions" value={upcoming.length} description="Booked with you" icon={CalendarDays}/><Stat label="Published slots" value={data.slots.length} description="Future availability including reservations" icon={Clock} color="violet"/><Stat label="Shared assessments" value={upcoming.filter((b:any)=>b.consent).length} description="Consent granted for these sessions" icon={ShieldCheck} color="peach"/></div>:null}{page!=='sessions'?<section className="panel"><div className="section-head"><div><h2>Your availability</h2><p>Publish 30-minute slots on the hour or half hour.</p></div><span className="pill">Input and display · PKT</span></div><form className="inline-form" onSubmit={e=>{e.preventDefault();const d=new Date(`${starts}:00+05:00`);act(async()=>{await api('/slots','POST',{startsAt:d.toISOString()});setStarts('');},'Availability published.');}}><label>Start time in Pakistan<input required type="datetime-local" step="1800" value={starts} onChange={e=>setStarts(e.target.value)}/></label><Button className="primary" type="submit" busy={busy}><Plus size={17}/>Publish slot</Button></form><div className="availability-list">{data.slots.length?data.slots.map((s:any)=><div key={s.id} className="availability-row"><CalendarDays size={17}/><span>{dateTime(s.starts_at)} PKT</span><span className={`status ${s.reserved?'booked':'available'}`}>{s.reserved?'Reserved':'Available'}</span><button className="icon-button" aria-label={`Remove slot ${dateTime(s.starts_at)}`} disabled={busy||s.reserved} onClick={()=>act(()=>api(`/slots/${s.id}`,'DELETE'),'Slot removed.')}><Trash2 size={16}/></button></div>):<p className="muted">No future slots. Publish your first available time.</p>}</div></section>:null}{page!=='availability'?<section className="panel space-top"><div className="section-head"><div><h2>Student sessions</h2><p>Assessment sharing is checked on every request.</p></div></div>{data.bookings.length?data.bookings.map((b:any)=><article key={b.id} className="booking-card"><span className="avatar large">{initials(b.student_name)}</span><div className="booking-info"><h3>{b.student_name}</h3><p>{dateTime(b.starts_at)} PKT · 30 minutes</p><span className={`status ${b.status}`}>{b.status}</span><span className="sharing-status"><ShieldCheck size={12}/>{b.consent&&b.status==='booked'?'Results shared':'Results private'}</span></div><div className="booking-actions"><Button onClick={()=>open(b)}><Eye size={16}/>Session workspace</Button>{b.status==='booked'?<Button className="danger ghost" disabled={busy} onClick={()=>act(()=>api(`/bookings/${b.id}`,'PATCH',{status:'cancelled'}),'Session cancelled.')}>Cancel</Button>:null}</div></article>):<Empty title="Your sessions will appear here">Publish availability so students can book a time.</Empty>}</section>:null}{selectedBooking?<Modal title={`Session with ${selectedBooking.student_name}`} onClose={()=>setSelected(undefined)} wide>{fetching?<div className="loading-panel"><LoaderCircle className="spin"/></div>:<>{selectedBooking.consent&&selectedBooking.status==='booked'&&context?<><div className="context-grid"><Radar scores={context.assessment?.scores??{}}/><div><h3>Shared student context</h3><p>{context.student.degree||'Degree not supplied'}{context.student.semester?` · Semester ${context.student.semester}`:''}</p>{context.matches.slice(0,5).map((m:Match)=><div className="compact-row" key={m.career.id}><span>{m.career.title}</span><strong>{m.score}%</strong></div>)}</div></div>{context.assessment?<div className="shared-skills"><h3>Shared skill self-ratings</h3><div className="tags">{Object.entries(context.assessment.skills).map(([k,v])=><span key={k}>{skillName(k)} · {String(v)}/5</span>)}</div></div>:<p>No assessment completed yet.</p>}</>:<p className="privacy-message"><LockKeyhole size={20}/>Assessment results are private for this booking. The student can grant or withdraw consent from their consultations page.</p>}<form onSubmit={e=>{e.preventDefault();act(()=>api(`/bookings/${selectedBooking.id}/note`,'PUT',{note}),'Private session notes saved.');}}><label>Private counsellor notes<textarea rows={5} maxLength={5000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Keep only relevant session observations."/></label><p className="fine-print">Visible only to the assigned counsellor through this workspace. Deleted with the student’s account.</p><Button className="primary" type="submit" busy={busy} disabled={selectedBooking.status!=='booked'}>Save notes<Check size={16}/></Button></form></>}</Modal>:null}</>;}
function AdminOverview({data,careers,go}:{data:any;careers:Career[];go:(s:string)=>void}){const a=data.analytics,pending=data.proposals.filter((p:any)=>p.status==='pending').length;const max=Math.max(...a.top.map((r:any)=>r.count),1);return <><PageHeading title="A clearer view of the platform" eyebrow="ADMINISTRATOR WORKSPACE">Keep career information useful, publishing controlled and performance measurable.</PageHeading><div className="stats-grid four"><Stat label="Completed assessments" value={a.assessments} description="Includes seeded records in demo mode" icon={ClipboardList}/><Stat label="Student accounts" value={a.students} description="Registered on this instance" icon={Users} color="violet"/><Stat label="Average relevance" value={a.average_rating?`${Number(a.average_rating).toFixed(1)}/5`:'No ratings'} description={`${a.feedback_count} relevance feedback records`} icon={Target} color="peach"/><Stat label="Pending reviews" value={pending} description="Expert submissions awaiting review" icon={FileCheck} color="blue"/></div><div className="dashboard-columns"><section className="panel"><div className="section-head"><div><h2>Most recommended careers</h2><p>Appearances in stored top-10 assessment results.</p></div></div><div className="bar-chart">{a.top.length?a.top.map((r:any,i:number)=><div className="bar-row" key={r.title}><div><span>{r.title}</span><strong>{r.count}</strong></div><div className="progress-track"><i style={{width:`${r.count/max*100}%`,background:i%2?'#a99aff':'#b5f5c4'}}/></div></div>):<p>No assessments yet.</p>}</div></section><section className="panel admin-actions"><h2>Keep the knowledge base honest</h2><p>{careers.filter(c=>c.active).length} active careers · {careers.filter(c=>c.reviewStatus.startsWith('Starter')).length} profiles awaiting content review.</p><button className="next-move" onClick={()=>go('knowledge')}><BookOpen/><div><h3>Review career profiles</h3><p>Check skills, degree mappings and sources.</p></div><ArrowUpRight/></button><button className="next-move" onClick={()=>go('reviews')}><FileCheck/><div><h3>Moderate expert updates</h3><p>{pending} submissions awaiting a decision.</p></div><ArrowUpRight/></button><button className="next-move" onClick={()=>go('scoring')}><SlidersHorizontal/><div><h3>Inspect scoring weights</h3><p>Changes affect the current recommendation view.</p></div><ArrowUpRight/></button><p className="education-note">These are operational counts. They do not demonstrate the proposal’s pilot relevance, uptime or 50-user performance targets.</p></section></div></>;}
const blankCareer=():Career=>({id:'',title:'',category:'Technology',summary:'',interests:{R:20,I:80,A:40,S:20,E:30,C:50},skills:{programming:3,communication:3},degrees:[],active:true,source:'https://www.onetonline.org/find/',reviewStatus:'Starter profile — expert review required'});
function CareerEditor({career,expert=false,busy,onSave,onClose}:{career:Career;expert?:boolean;busy:boolean;onSave:(c:Career,reason?:string)=>void;onClose:()=>void}){const [c,setC]=useState<Career>(structuredClone(career)),[degrees,setDegrees]=useState(career.degrees.join(', ')),[reason,setReason]=useState('');return <Modal title={expert?'Propose a career profile update':career.id?'Edit career profile':'Add a career profile'} onClose={onClose} wide><form onSubmit={e=>{e.preventDefault();onSave({...c,degrees:degrees.split(',').map(s=>s.trim()).filter(Boolean)},reason);}}>{!expert?<div className="form-grid"><label>Career identifier<input required disabled={!!career.id} pattern="[a-z0-9-]{3,70}" value={c.id} onChange={e=>setC({...c,id:e.target.value})} placeholder="example-career"/></label><label>Title<input required minLength={3} maxLength={100} value={c.title} onChange={e=>setC({...c,title:e.target.value})}/></label><label>Field<select value={c.category} onChange={e=>setC({...c,category:e.target.value})}>{['Technology','Data and Research','Design and Media','Business','People and Education','Finance','Engineering'].map(x=><option key={x}>{x}</option>)}</select></label><label>Publication status<select value={c.active?'active':'inactive'} onChange={e=>setC({...c,active:e.target.value==='active'})}><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div>:<p className="mint-text">Editing {career.title}. Your changes stay unpublished until an administrator approves them.</p>}<label>Career summary<textarea required minLength={15} maxLength={1500} rows={3} value={c.summary} onChange={e=>setC({...c,summary:e.target.value})}/></label><label>Degree backgrounds separated by commas<input maxLength={1500} value={degrees} onChange={e=>setDegrees(e.target.value)} placeholder="BS Computer Science, BS Software Engineering"/></label><h3>RIASEC career profile</h3><div className="vector-editor">{types.map(t=><label key={t}>{interestInfo[t].name}<input type="number" min={0} max={100} required value={c.interests[t]} onChange={e=>setC({...c,interests:{...c.interests,[t]:Number(e.target.value)}})}/></label>)}</div><h3>Required skills and levels</h3><div className="skill-editor">{skillCatalog.map(s=><label key={s.id}>{s.name}<select value={c.skills[s.id]??0} onChange={e=>{const skills={...c.skills};if(Number(e.target.value))skills[s.id]=Number(e.target.value);else delete skills[s.id];setC({...c,skills});}}><option value={0}>Not required</option>{[1,2,3,4,5].map(n=><option key={n} value={n}>Level {n}</option>)}</select></label>)}</div><label>Supporting source URL<input type="url" required pattern="https://.*" maxLength={500} value={c.source} onChange={e=>setC({...c,source:e.target.value})}/></label>{expert?<label>Explain your proposed changes<textarea required minLength={15} maxLength={2000} rows={3} value={reason} onChange={e=>setReason(e.target.value)}/></label>:<label>Content review status<select value={c.reviewStatus} onChange={e=>setC({...c,reviewStatus:e.target.value})}><option>Starter profile — expert review required</option><option>Reviewed by administrator</option></select></label>}<div className="modal-actions"><Button onClick={onClose} type="button">Cancel</Button><Button type="submit" busy={busy} className="primary">{expert?'Submit for review':'Save career'}<Check size={16}/></Button></div></form></Modal>;}
function KnowledgePage({careers,busy,act}:{careers:Career[];busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void}){const [editing,setEditing]=useState<Career>(),[search,setSearch]=useState('');return <><PageHeading title="Career knowledge base" eyebrow="CONTENT MANAGEMENT" action={<Button className="primary" onClick={()=>setEditing(blankCareer())}><Plus size={17}/>Add career</Button>}>Maintain the career profiles that drive every recommendation.</PageHeading><div className="panel"><div className="section-head"><h2>{careers.length} career profiles</h2><label className="search-box"><Search size={16}/><input placeholder="Find a career" aria-label="Search knowledge base" value={search} onChange={e=>setSearch(e.target.value)}/></label></div><div className="table-scroll"><table><thead><tr><th>Career</th><th>Field</th><th>Required skills</th><th>Status</th><th>Content review</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{careers.filter(c=>c.title.toLowerCase().includes(search.toLowerCase())).map(c=><tr key={c.id}><td><strong>{c.title}</strong><small>{c.id}</small></td><td>{c.category}</td><td>{Object.keys(c.skills).length}</td><td><span className={`status ${c.active?'available':'cancelled'}`}>{c.active?'Active':'Inactive'}</span></td><td><span className="subtle">{c.reviewStatus.startsWith('Starter')?'Review needed':'Reviewed'}</span></td><td><Button onClick={()=>setEditing(c)}>Edit<ArrowUpRight size={14}/></Button></td></tr>)}</tbody></table></div></div>{editing?<CareerEditor career={editing} busy={busy} onClose={()=>setEditing(undefined)} onSave={c=>act(async()=>{await api(`/admin/careers${editing.id?`/${editing.id}`:''}`,editing.id?'PUT':'POST',c);setEditing(undefined);},'Career profile saved.')}/>:null}</>;}
function Proposals({data,admin=false,busy,act}:{data:any[];admin?:boolean;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void}){return <><PageHeading title={admin?'Review before publishing':'Your contributions'} eyebrow={admin?'EXPERT REVIEW QUEUE':'INDUSTRY KNOWLEDGE'}>{admin?'Approve an update to apply its profile changes atomically.':'Every submission stays unpublished until an administrator approves it.'}</PageHeading>{data.length?<div className="proposal-list">{data.map(p=><article className="panel proposal" key={p.id}><div className="section-head"><div><span className="eyebrow">{p.career_title}</span><h3>{p.expert_name}</h3></div><span className={`status ${p.status}`}>{p.status}</span></div><p>{p.summary}</p><a className="resource-link" href={p.source} target="_blank" rel="noreferrer">Supporting source<ExternalLink size={14}/></a><details><summary>Inspect proposed changes</summary><p>{p.patch.summary}</p><div className="tags">{Object.entries(p.patch.skills).map(([s,n])=><span key={s}>{skillName(s)} · level {String(n)}</span>)}</div><p className="subtle">RIASEC: {types.map(t=>`${t} ${p.patch.interests[t]}`).join(' · ')}</p><p className="subtle">Degrees: {p.patch.degrees.join(', ')||'Open to multiple backgrounds'}</p></details><div className="section-head"><small className="muted">Submitted {dateTime(p.created_at)} PKT</small>{admin&&p.status==='pending'?<div className="inline-actions"><Button disabled={busy} onClick={()=>act(()=>api(`/admin/proposals/${p.id}`,'PATCH',{approve:false}),'Proposal rejected.')}>Reject<X size={15}/></Button><Button className="primary" busy={busy} onClick={()=>act(()=>api(`/admin/proposals/${p.id}`,'PATCH',{approve:true}),'Update approved and published.')}>Approve and publish<Check size={15}/></Button></div>:null}</div></article>)}</div>:<div className="panel"><Empty title={admin?'The review queue is clear':'No submissions yet'}>{admin?'Expert updates will appear here for approval.':'Choose a career and propose an evidence-supported improvement.'}</Empty></div>}</>;}
function UsersPage({users,self,busy,act}:{users:User[];self:string;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void}){const [roles,setRoles]=useState<Record<string,Role>>({});return <><PageHeading title="The right access for each person" eyebrow="USER MANAGEMENT">Public registration always creates students. Assign staff permissions deliberately.</PageHeading><div className="panel table-scroll"><table><thead><tr><th>Account</th><th>Current role</th><th>Assign role</th><th>Action</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><strong>{u.name}{u.id===self?' (you)':''}</strong><small>{u.email}</small></td><td>{roleLabel[u.role]}</td><td><select aria-label={`Role for ${u.name}`} value={roles[u.id]??u.role} disabled={u.id===self||busy} onChange={e=>setRoles({...roles,[u.id]:e.target.value as Role})}>{Object.entries(roleLabel).map(([r,label])=><option key={r} value={r}>{label}</option>)}</select></td><td><Button disabled={u.id===self||busy||!roles[u.id]||roles[u.id]===u.role} onClick={()=>act(()=>api(`/admin/users/${u.id}/role`,'PATCH',{role:roles[u.id]}),'Role updated.')}>Save<Check size={14}/></Button></td></tr>)}</tbody></table></div></>;}
function ScoringPage({weights,busy,act}:{weights:Weights;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void}){const [w,setW]=useState(weights);const sum=w.interest+w.skills+w.degree;return <><PageHeading title="Make the scoring explicit" eyebrow="RECOMMENDATION SETTINGS">Weights must add up to 1. Changes affect current matches; completed assessments retain their original weight and top-10 snapshots.</PageHeading><div className="scoring-layout"><form className="panel" onSubmit={e=>{e.preventDefault();act(()=>api('/admin/weights','PUT',w),'Scoring weights updated.');}}><h2>Hybrid model weights</h2>{(['interest','skills','degree'] as const).map((k,i)=><label className="weight-input" key={k}><div><strong>{['Interest alignment','Skill readiness','Academic fit'][i]}</strong><span>{Math.round(w[k]*100)}%</span></div><input type="range" step="0.05" min={0} max={1} value={w[k]} onChange={e=>setW({...w,[k]:Number(e.target.value)})}/><small>{['Cosine similarity between two RIASEC vectors.','Mean capped skill coverage across required skills.','1 for a listed degree; 0.25 for other degrees; 0.5 if omitted.'][i]}</small></label>)}<div className="compact-row"><strong>Total weight</strong><strong className={Math.abs(sum-1)<.000001?'mint-text':'error-text'}>{sum.toFixed(2)} / 1.00</strong></div><Button className="primary full" type="submit" busy={busy} disabled={Math.abs(sum-1)>.000001}>Save weights<Check size={16}/></Button></form><section className="panel"><h2>How the model behaves</h2><p>The weighted sum produces a score from 0 to 100. The three factor contributions are displayed with every career match.</p><h3>Cold starts</h3><p>New students complete the assessment before receiving personal matches. Missing optional degree information uses a neutral academic value.</p><h3>No hard eligibility exclusion</h3><p>A degree outside the starter list reduces academic fit but does not eliminate a career. This supports exploration and avoids treating editorial data as professional admission rules.</p><h3>Fairness and evaluation</h3><p>Gender is not collected or used. This alone does not establish fairness. Compare all three variants with real pilot judgements before tuning weights.</p></section></div></>;}
function ExpertPage({page,careers,proposals,busy,act,go}:{page:string;careers:Career[];proposals:any[];busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void;go:(s:string)=>void}){const [selected,setSelected]=useState<Career>(),[careerId,setCareerId]=useState(''),[search,setSearch]=useState('');if(page==='settings')return null;if(page==='contributions')return <Proposals data={proposals} busy={busy} act={act}/>;return <><PageHeading title={page==='submit'?'Share what your industry knows':'Help keep career guidance useful'} eyebrow="INDUSTRY EXPERT WORKSPACE">Propose a profile improvement with a supporting source. Administrators review every change.</PageHeading>{page==='overview'?<div className="stats-grid"><Stat label="Your submissions" value={proposals.length} description="All career profile updates" icon={Send}/><Stat label="Pending review" value={proposals.filter(p=>p.status==='pending').length} description="Unpublished until approved" icon={Clock} color="violet"/><Stat label="Published updates" value={proposals.filter(p=>p.status==='approved').length} description="Approved by an administrator" icon={CheckCircle2} color="peach"/></div>:null}<section className="panel"><div className="section-head"><div><h2>Choose a career to improve</h2><p>Update skills, interests, degree backgrounds or the career summary.</p></div></div><div className="inline-form"><label className="grow">Career profile<select value={careerId} onChange={e=>setCareerId(e.target.value)}><option value="">Select a career</option>{careers.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><Button className="primary" disabled={!careerId} onClick={()=>setSelected(careers.find(c=>c.id===careerId))}>Propose update<ArrowUpRight size={16}/></Button></div><p className="fine-print">The source should support the proposed changes. Submitting an update does not grant publishing rights.</p></section>{page==='overview'?<><div className="section-head outside"><h2>Recent contributions</h2><button className="text-button" onClick={()=>go('contributions')}>View all<ArrowRight size={16}/></button></div>{proposals.length?<div className="panel">{proposals.slice(0,5).map(p=><div className="compact-row" key={p.id}><span>{p.career_title}</span><span className={`status ${p.status}`}>{p.status}</span></div>)}</div>:<div className="panel"><Empty title="Your experience can improve the next recommendation">Choose a career above to submit your first update.</Empty></div>}</>:null}{selected?<CareerEditor career={selected} expert busy={busy} onClose={()=>setSelected(undefined)} onSave={(c,reason)=>act(async()=>{await api('/proposals','POST',{careerId:c.id,summary:reason,source:c.source,patch:{summary:c.summary,skills:c.skills,interests:c.interests,degrees:c.degrees}});setSelected(undefined);},'Your update was submitted for administrator review.')}/>:null}</>;}
function SettingsPage({user,onUser,busy,act,onDelete,notify}:{user:User;onUser:(u:User)=>void;busy:boolean;act:(f:()=>Promise<unknown>,s?:string)=>void;onDelete:()=>void;notify:(s:string)=>void}){const [p,setP]=useState(user),[deleting,setDeleting]=useState(false),[password,setPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[removing,setRemoving]=useState(false);async function remove(e:FormEvent){e.preventDefault();setRemoving(true);try{await api('/me','DELETE',{password,confirmation});onDelete();notify('Your student account and related application data were deleted.');}catch(e){notify((e as Error).message);}finally{setRemoving(false);}}return <><PageHeading title="Your profile and your privacy" eyebrow="SETTINGS">Keep your profile up to date. Academic details are optional and affect the academic fit component.</PageHeading><div className="settings-layout"><form className="panel" onSubmit={e=>{e.preventDefault();act(async()=>{const u=await api<User>('/me','PUT',{name:p.name,degree:p.degree||null,semester:p.semester,cgpa:p.cgpa,bio:p.bio,specialty:p.specialty});onUser(u);},'Profile updated.');}}><div className="profile-summary"><span className="avatar extra-large">{initials(p.name)}</span><div><h2>{user.name}</h2><p>{user.email}</p><span className="pill">{roleLabel[user.role]}</span></div></div><div className="form-grid"><label>Full name<input required minLength={2} maxLength={80} value={p.name} onChange={e=>setP({...p,name:e.target.value})}/></label><label>Degree programme<input value={p.degree??''} maxLength={100} list="degrees" placeholder="Optional" onChange={e=>setP({...p,degree:e.target.value||null})}/><datalist id="degrees">{['BS Software Engineering','BS Computer Science','BBA','BS Psychology','BS Design','BS Mathematics','BS Education','BS Economics','BS Electrical Engineering'].map(d=><option key={d}>{d}</option>)}</datalist></label><label>Semester<input type="number" min={1} max={16} value={p.semester??''} placeholder="Optional" onChange={e=>setP({...p,semester:e.target.value?Number(e.target.value):null})}/></label><label>CGPA out of 4<input type="number" min={0} max={4} step="0.01" value={p.cgpa??''} placeholder="Optional" onChange={e=>setP({...p,cgpa:e.target.value?Number(e.target.value):null})}/></label></div>{user.role!=='student'?<><label>Specialty<input maxLength={100} value={p.specialty} onChange={e=>setP({...p,specialty:e.target.value})}/></label><label>Public biography<textarea maxLength={1000} rows={3} value={p.bio} onChange={e=>setP({...p,bio:e.target.value})}/></label></>:null}<Button className="primary" type="submit" busy={busy}>Save profile<Check size={16}/></Button></form><section className="panel privacy-panel"><ShieldCheck size={30}/><h2>Privacy by choice</h2><p>CareerCompass does not collect gender, national ID or phone numbers. Degree, semester and CGPA are optional. Only degree is used in scoring.</p><h3>Consent for consultations</h3><p>Each booking has its own sharing choice. Counsellors see results only when that booking is active and consent is granted. You can withdraw consent any time.</p><h3>Account security</h3><p>Your email and role cannot be changed from profile fields. Sessions use HTTP-only cookies. Student registration never grants staff permissions.</p>{user.role==='student'?<div className="delete-account"><h3>Delete your student account</h3><p>Deletes your profile, assessments, bookings, notes, feedback, drafts and roadmap progress. This is permanent.</p><Button className="danger" onClick={()=>setDeleting(true)}><Trash2 size={16}/>Delete account</Button></div>:null}</section></div>{deleting?<Modal title="Delete your student account" onClose={()=>setDeleting(false)}><p>Your personal and assessment records will be permanently removed. Re-enter your password and type DELETE to confirm.</p><form onSubmit={remove}><label>Current password<input type="password" required minLength={8} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label><label>Type DELETE<input required pattern="DELETE" value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label><div className="modal-actions"><Button type="button" onClick={()=>setDeleting(false)}>Keep my account</Button><Button type="submit" className="danger" busy={removing} disabled={confirmation!=='DELETE'}>Permanently delete<Trash2 size={16}/></Button></div></form></Modal>:null}</>;}
createRoot(document.getElementById('root')!).render(<App/>);
